def comps(g, bg):
    # connected components of non-bg cells (4-conn)
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c={(i,j)}
                while st:
                    a,b=st.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]!=bg and (x,y) not in seen:
                            seen.add((x,y)); c.add((x,y)); st.append((x,y))
                res.append(c)
    return res

