# Operation families over parameters
def ops(S, mks):
    res=[]
    for m in mks:
        for dr in range(-15,16):
            for dc in range(-15,16):
                # translate shape by (dr,dc) then recolor; require every shape cell maps into tgt
                im={(i+dr,j+dc) for i,j in S}
                if im <= tgt and len(im)==len(S):
                    res.append(('trans',(dr,dc)))
    for m in mks:
        for dr in range(-15,16):
            for dc in range(-15,16):
                # reflect about marker: p -> 2*m + (dr,diff) where diff = p-m
                im={(2*m[0]+i-dr, 2*m[1]+j-dc) for i,j in S}
                if im <= tgt and len(im)==len(S):
                    res.append(('ref_m',m,(dr,dc)))
    for m in mks:
        for r0 in range(-25,26):
            for c0 in range(-25,26):
                # rotate 180 about (r0,c0): p -> (2*r0-i, 2*c0-j)
                im={(2*r0-i, 2*c0-j) for i,j in S}
                if im <= tgt and len(im)==len(S):
                    res.append(('rot180',(r0,c0)))
        for r0 in range(-25,26):
            for c0 in range(-25,26):
                # rotate 90 about (r0,c0): p -> (r0+(j-c0), c0-(i-r0))
                im={(r0+j-c0, c0-(i-r0)) for i,j in S}
                if im <= tgt and len(im)==len(S):
                    res.append(('rot90',(r0,c0)))
    return res

