def analyze(i):
    gi=G[f'Demo pair {i} input']; go=G[f'Demo pair {i} output']
    H,W=len(gi),len(gi[0]); bg=gi[0][0]
    # find template: largest connected same-value component
    best=[]
    for v in range(10):
        seen=set(); 
        for r in range(H):
            for c in range(W):
                if gi[r][c]==v and (r,c) not in seen:
                    q=deque([(r,c)]); seen.add((r,c)); comp=[(r,c)]
                    while q:
                        rr,cc=q.popleft()
                        for dr in(-1,0,1):
                            for dc in(-1,0,1):
                                n=(rr+dr,cc+dc)
                                if 0<=n[0]<H and 0<=n[1]<W and gi[n[0]][n[1]]==v and n not in seen:
                                    seen.add(n); q.append(n); comp.append(n)
                    best.append((len(comp),comp,v))
    best.sort(reverse=True)
    nsz,ncomp,nval=best[0]
    rs=[p[0] for p in ncomp]; cs=[p[1] for p in ncomp]
    t={(p[0]-min(rs),p[1]-min(cs)) for p in ncomp}
    markers=[(r,c) for r in range(H) for c in range(W) if gi[r][c]!=bg and (r,c) not in ncomp]
    mset={(r,c) for r,c in markers}
    return dict(bg=bg,t=t,mset=mset,grid=gi,output=go,H=H,W=W)
